class Solution {
public:
    vector<long long> minCost(int n, vector<vector<int>>& roads, vector<int>& appleCost, int k) {
        vector<vector<pair<int,int>>> graph(n);
        for (auto& e : roads) {
            graph[e[0] - 1].push_back({e[1] - 1, e[2]});
            graph[e[1] - 1].push_back({e[0] - 1, e[2]});
        }
        vector<long long> dist(appleCost.begin(), appleCost.end());
        priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<pair<long long,int>>> pq;
        for (int i = 0; i < n; ++i) pq.push({dist[i], i});
        while (!pq.empty()) {
            auto top = pq.top(); pq.pop();
            long long d = top.first;
            int u = top.second;
            if (d != dist[u]) continue;
            for (auto edge : graph[u]) {
                long long next = d + (long long)(k + 1) * edge.second;
                if (next < dist[edge.first]) {
                    dist[edge.first] = next;
                    pq.push({next, edge.first});
                }
            }
        }
        return dist;
    }
};
